import streamlit as st
import pandas as pd
import plotly.express as px

# 1. Page Configuration
st.set_page_config(page_title="StS2 Run Analyzer", layout="wide")
st.title("Slay the Spire 2: Win Rate Analysis")

# 2. Load the flat JSON data generated by your batch processor
@st.cache_data
def load_data():
    return pd.read_json("data/parsed_runs_dataset.json")

df = load_data()

# 3. Sidebar Interactive Filters
st.sidebar.header("Filters")

# Toggle for abandoned runs
include_abandoned = st.sidebar.checkbox("Include Abandoned Runs", value=False)

# Toggle for a10 only
toggle_a10 = st.sidebar.checkbox("Only Ascension 10 Runs", value = False)

metric_choice = st.sidebar.selectbox(
    "Select Metric to Visualize",
    options=["Win Rate (%)", "Games Played", "Average Floor Reached"],
)

# 4. Apply Filters to Pandas DataFrame
filtered_df = df.copy()

if not include_abandoned:
    filtered_df = filtered_df[filtered_df["abandonded"] == False]

if toggle_a10:
    filtered_df = filtered_df[filtered_df["ascension_level"] == 10]

if not filtered_df.empty:

    # Dynamically alter the Pandas calculation based on the dropdown
    if metric_choice == "Win Rate (%)":
        plot_data = filtered_df.groupby("character_chosen", as_index=False)[
            "victory"
        ].mean()
        plot_data["value"] = (plot_data["victory"] * 100).round(1)
        y_label = "Win Rate (%)"
        text_format = "%{text}%"

    elif metric_choice == "Games Played":
        plot_data = filtered_df.groupby("character_chosen", as_index=False).size()
        plot_data.rename(columns={"size": "value"}, inplace=True)
        y_label = "Total Games Played"
        text_format = "%{text}"

    elif metric_choice == "Average Floor Reached":
        plot_data = filtered_df.groupby("character_chosen", as_index=False)[
            "floor_reached"
        ].mean()
        plot_data["value"] = plot_data["floor_reached"].round(1)
        y_label = "Average Floor"
        text_format = "%{text}"

    # 6. Build the Interactive Plotly Bar Chart
    # By mapping y="value", the same chart logic works for all three metrics
    fig = px.bar(
        plot_data,
        x="character_chosen",
        y="value",
        title=f"{metric_choice} by Character",
        labels={"character_chosen": "Character", "value": y_label},
        text="value",
        color="character_chosen",
    )

    # Format the text labels on the bars
    fig.update_traces(texttemplate=text_format, textposition="outside")

    # Lock Y-axis to 0-100% only if we are showing Win Rate
    if metric_choice == "Win Rate (%)":
        fig.update_yaxes(range=[0, 100])
    else:
        # Give a little headroom for the text labels on the other charts
        max_val = plot_data["value"].max()
        fig.update_yaxes(range=[0, max_val * 1.15])

    # Render the graph in Streamlit
    st.plotly_chart(fig, use_container_width=True)

else:
    st.warning("No runs match the selected filters.")

st.divider()  # Adds a horizontal line for visual separation
st.subheader("Card Pick & Skip Analysis")

# 1. Character Filter Dropdown
available_chars = filtered_df["character_chosen"].unique()

if len(available_chars) > 0:
    selected_char = st.selectbox("Select Character to Analyze", options=available_chars)
    char_df = filtered_df[filtered_df["character_chosen"] == selected_char]

    # 2. Unnest the card_choices array
    # .explode() takes a list like [Choice1, Choice2] and creates a new dataframe row for each
    exploded_choices = char_df.explode("card_choices").dropna(subset=["card_choices"])

    if not exploded_choices.empty:
        # 3. Extract the 'picked' card names
        picked_series = (
            exploded_choices["card_choices"]
            .apply(
                lambda c: (
                    c.get("picked", {}).get("name")
                    if isinstance(c, dict) and c.get("picked")
                    else None
                )
            )
            .dropna()
        )

        # 4. Extract the 'not_picked' card names
        # Since not_picked is a list of cards, we extract the list of names, then explode again
        not_picked_series = (
            exploded_choices["card_choices"]
            .apply(
                lambda c: (
                    [card.get("name") for card in c.get("not_picked", [])]
                    if isinstance(c, dict)
                    else []
                )
            )
            .explode()
            .dropna()
        )

        # 5. Display the top results side-by-side
        col1, col2 = st.columns(2)

        with col1:
            st.markdown("### Most Picked")
            if not picked_series.empty:
                top_picked = picked_series.value_counts().reset_index()
                top_picked.columns = ["Card", "Times Picked"]

                # Display the #1 card as a large metric, and the top 5 as a table
                st.metric("Top Pick", top_picked.iloc[0]["Card"])
                st.dataframe(top_picked.head(5), hide_index=True)
            else:
                st.write("No card pick data available.")

        with col2:
            st.markdown("### Most Ignored")
            if not not_picked_series.empty:
                top_ignored = not_picked_series.value_counts().reset_index()
                top_ignored.columns = ["Card", "Times Skipped"]

                st.metric("Top Skip", top_ignored.iloc[0]["Card"])
                st.dataframe(top_ignored.head(5), hide_index=True)
            else:
                st.write("No card skip data available.")
else:
    st.info("No runs available to analyze card choices.")
